import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static int addModulo(int x, int y) {
        x += y;
        if (x >= MOD) x -= MOD;
        return x;
    }

    static int multiplyModulo(int x, int y) {
        long res = 1L * x * y;
        if (res >= MOD) res %= MOD;
        return (int) res;
    }

    static int subtractModulo(int x, int y) {
        x -= y;
        if (x < 0) x += MOD;
        return x;
    }

    static int powModulo(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = multiplyModulo(res, base);
            base = multiplyModulo(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int getLowbitValue(int x) {
        return x & (-x);
    }

    static int n;
    static int[][] a = new int[10][10];
    static int[][] ch;
    static int[][] qarr;
    static int[][] dparr;
    static Map<BitSet, Integer> idMap = new HashMap<>();
    static int cnt = 0;

    static int dfsBitset(BitSet s) {
        if (idMap.containsKey(s)) return idMap.get(s);
        cnt++;
        int id = cnt;
        idMap.put((BitSet) s.clone(), id);
        ch[id] = new int[1 << n];
        for (int i = 0; i < (1 << n); i++) {
            BitSet tmp = (BitSet) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = getLowbitValue(x);
                        if (s.get(j ^ t)) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id][i] = dfsBitset(tmp);
        }
        return id;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        n = Integer.parseInt(br.readLine());
        ch = new int[10010][];
        qarr = new int[10][1 << 10];
        dparr = new int[11][10010];

        // Initialize the first call to dfsBitset with a BitSet of size n with only the first bit set
        BitSet initialSet = new BitSet(n);
        initialSet.set(0);
        dfsBitset(initialSet);

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                a[i][j] = Integer.parseInt(st.nextToken());
                a[i][j] = multiplyModulo(a[i][j], powModulo(100, MOD - 2));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                qarr[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        qarr[i][j] = multiplyModulo(qarr[i][j], a[i][k]);
                    } else {
                        qarr[i][j] = multiplyModulo(qarr[i][j], subtractModulo(1, a[i][k]));
                    }
                }
            }
        }

        dparr[0][1] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= cnt; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int index = ch[j][k];
                    dparr[i][index] = addModulo(dparr[i][index], multiplyModulo(dparr[i - 1][j], qarr[i - 1][k]));
                }
            }
        }

        BitSet bits = new BitSet(n);
        bits.set(0, n);
        int result = dparr[n][idMap.get(bits)];
        System.out.println(result);
    }
}
